/**
 * External dependencies
 */
import type { ScopeRule, ScopeRuleId } from '@nab/types';

export type ScopeAction = SetScopeRules | SetPageViewExclusions;

export function setScopeRules(
	rules: ReadonlyArray< ScopeRule >
): SetScopeRules {
	return {
		type: 'SET_SCOPE_RULES',
		rules,
	};
}

export function setPageViewExclusions(
	rules: ReadonlyArray< ScopeRuleId >
): SetPageViewExclusions {
	return {
		type: 'SET_PAGE_VIEW_EXCLUSIONS',
		rules,
	};
}

// =====
// TYPES
// =====

type SetScopeRules = {
	readonly type: 'SET_SCOPE_RULES';
	readonly rules: ReadonlyArray< ScopeRule >;
};

type SetPageViewExclusions = {
	readonly type: 'SET_PAGE_VIEW_EXCLUSIONS';
	readonly rules: ReadonlyArray< ScopeRuleId >;
};
