/**
 * External dependencies
 */
import { isEqual, keyBy } from 'lodash';
import { EMPTY_ARRAY, EMPTY_OBJECT } from '@nab/utils';
import type { AnyAction } from '@nab/types';

/**
 * Internal dependencies
 */
import { INIT_STATE as IS } from '../config';

import type { State as FullState } from '../types';
type State = FullState[ 'experiment' ][ 'scope' ];

import type { ScopeAction } from '../actions/scope';
import type { SetupEditor } from '../actions/editor';
type Action = ScopeAction | SetupEditor;

const INIT_STATE = IS.experiment.scope;

const EMPTY_SCOPE = {
	rules: EMPTY_OBJECT,
	pageViewExclusions: EMPTY_ARRAY,
} as const;

export function scope( state = INIT_STATE, action: AnyAction ): State {
	return actualReducer( state, action as Action ) ?? state;
}

function actualReducer( state: State, action: Action ): State {
	switch ( action.type ) {
		case 'SET_SCOPE_RULES': {
			const rules = state.rules;
			const newRules = action.rules.map( ( rule ) =>
				rules[ rule.id ] && isEqual( rules[ rule.id ], rule )
					? rules[ rule.id ]
					: rule
			);
			return {
				...state,
				rules: keyBy( newRules, 'id' ),
			};
		}

		case 'SET_PAGE_VIEW_EXCLUSIONS':
			return {
				...state,
				pageViewExclusions: action.rules,
			};

		case 'SETUP_EDITOR': {
			if ( 'nab/heatmap' === action.experiment.type ) {
				return EMPTY_SCOPE;
			}

			const newRules = keyBy( action.experiment.scope, 'id' );
			if (
				isEqual( newRules, state.rules ) &&
				isEqual(
					action.experiment.pageViewScopeExclusions,
					state.pageViewExclusions
				)
			) {
				return state;
			}

			return {
				rules: newRules,
				pageViewExclusions: action.experiment.pageViewScopeExclusions,
			};
		}
	}
}
