/**
 * WordPress dependencies
 */
import { createSelector } from '@safe-wordpress/data';

/**
 * External dependencies
 */
import { values } from 'lodash';
import { isDefined } from '@nab/utils';
import type { ScopeRule, ScopeRuleId } from '@nab/types';

/**
 * Internal dependencies.
 */
import type { State } from '../types';

export const getScope = createSelector(
	( state: State ): ReadonlyArray< ScopeRule > =>
		values( state.experiment.scope.rules ).filter( isDefined ),
	( state: State ) => [ state.experiment.scope.rules ]
);

export function getPageViewExclusions(
	state: State
): ReadonlyArray< ScopeRuleId > {
	return state.experiment.scope.pageViewExclusions;
}
